  ('88903a85-7dce-59e5-abae-21af912f2874'::uuid, '0장 · 1절 · 설계도서', '표준시방서 · 전문시방서 · 공사시방서', '표준시방서는 국가가 제정한 시공기준의 표준(KCS), 전문시방서는 발주기관이 작성한 종합 시공기준, 공사시방서는 해당 현장 전용 시방서(계약문서).', '["표준(국가) → 전문(발주기관) → 공사(해당 현장) 순으로 구체화"]'::jsonb, false),
  ('e1c16cc3-6e33-5f99-b550-98c991deaafe'::uuid, '0장 · 1절 · 설계도서', '구조계산서', '구조물이 하중에 안전하도록 부재 단면·배근 등을 계산·검토한 문서. 구조기술사가 작성·날인.', '[]'::jsonb, false),
